/* Generated by scripts/sync-dashboard.mjs from extension/src/shared. Edit the original. */
// Which job boards the extension knows about, and how to build a search URL on
// each. This half is needed by the service worker and the options page, so it
// lives outside the content scripts; the DOM half lives in content/sites/.
//
// Adding a board means adding an entry here and an adapter there. Nothing else
// in the codebase should need to know which site a job came from.

const slug = (s) => String(s || '')
  .toLowerCase().trim()
  .replace(/[^a-z0-9]+/g, '-')
  .replace(/^-|-$/g, '');

// The config stores LinkedIn's own date codes; other boards want days.
export function datePostedDays(value) {
  if (value === 'r86400') return 1;
  if (value === 'r604800') return 7;
  if (value === 'r2592000') return 30;
  return 0;
}

export const SITES = {
  linkedin: {
    id: 'linkedin',
    name: 'LinkedIn',
    host: /(^|\.)linkedin\.com$/,
    matches: ['https://www.linkedin.com/*'],
    home: 'https://www.linkedin.com/jobs/',
    perPage: 25,
    // LinkedIn shows the job in a side pane, so a card is clicked.
    openStrategy: "click",
    // LinkedIn is the only board with a filter for "applications I can finish
    // in-page", so it is the only one where quick-apply-only is a real option.
    supportsQuickApplyFilter: true,
    quickApplyName: 'Easy Apply',

    searchUrl(search, keywords, start = 0, quickApplyOnly = true) {
      const u = new URL('https://www.linkedin.com/jobs/search/');
      const q = [keywords, search.extraQuery].filter(Boolean).join(' ').trim();
      if (q) u.searchParams.set('keywords', q);
      if (search.location) u.searchParams.set('location', search.location);
      if (search.geoId) u.searchParams.set('geoId', search.geoId);
      if (quickApplyOnly) u.searchParams.set('f_AL', 'true');
      if (search.datePosted) u.searchParams.set('f_TPR', search.datePosted);
      if (search.remote && search.remote.length) u.searchParams.set('f_WT', search.remote.join(','));
      if (search.experience && search.experience.length) u.searchParams.set('f_E', search.experience.join(','));
      if (search.sortBy) u.searchParams.set('sortBy', search.sortBy);
      if (start) u.searchParams.set('start', String(start));
      return u.toString();
    }
  },

  naukri: {
    id: 'naukri',
    name: 'Naukri',
    host: /(^|\.)naukri\.com$/,
    matches: ['https://www.naukri.com/*'],
    home: 'https://www.naukri.com/',
    perPage: 20,
    // Naukri and Indeed have real job pages: navigating is far more reliable
    // than clicking into a list that re-renders underneath us.
    openStrategy: "navigate",
    supportsQuickApplyFilter: false,
    quickApplyName: 'Apply',

    // Naukri reads the keyword and location from the query string, so the
    // path slug is only cosmetic - but it has to be there, and it has to be
    // plausible, or the page 404s.
    searchUrl(search, keywords, start = 0, _quickApplyOnly, profile = {}) {
      const path = [slug(keywords) || 'jobs', 'jobs',
        search.location ? 'in-' + slug(search.location) : ''].filter(Boolean).join('-');
      const u = new URL('https://www.naukri.com/' + path);
      u.searchParams.set('k', [keywords, search.extraQuery].filter(Boolean).join(' ').trim());
      if (search.location) u.searchParams.set('l', search.location);
      const years = Number(profile.defaultYears);
      if (Number.isFinite(years) && years > 0) u.searchParams.set('experience', String(Math.min(30, years)));
      const days = datePostedDays(search.datePosted);
      if (days) u.searchParams.set('jobAge', String(days));
      if (search.remote && search.remote.includes('2')) u.searchParams.set('wfhType', '2');
      const page = Math.floor(start / 20) + 1;
      if (page > 1) u.searchParams.set('pageNo', String(page));
      return u.toString();
    }
  },

  indeed: {
    id: 'indeed',
    name: 'Indeed',
    host: /(^|\.)indeed\.com$/,
    matches: ['https://*.indeed.com/*'],
    home: 'https://www.indeed.com/',
    perPage: 10,
    openStrategy: "navigate",
    supportsQuickApplyFilter: false,
    quickApplyName: 'Indeed Apply',
    // Indeed runs a different domain per country and the results differ by it.
    domains: ['www.indeed.com', 'in.indeed.com', 'uk.indeed.com', 'ca.indeed.com',
      'au.indeed.com', 'de.indeed.com', 'sg.indeed.com', 'ae.indeed.com'],

    searchUrl(search, keywords, start = 0, _quickApplyOnly, _profile, siteCfg = {}) {
      const domain = siteCfg.domain && this.domains.includes(siteCfg.domain)
        ? siteCfg.domain : 'www.indeed.com';
      const u = new URL('https://' + domain + '/jobs');
      u.searchParams.set('q', [keywords, search.extraQuery].filter(Boolean).join(' ').trim());
      if (search.location) u.searchParams.set('l', search.location);
      const days = datePostedDays(search.datePosted);
      if (days) u.searchParams.set('fromage', String(days));
      if (search.remote && search.remote.includes('2')) u.searchParams.set('sc', '0kf:attr(DSQF7);');
      if (search.sortBy === 'DD') u.searchParams.set('sort', 'date');
      if (start) u.searchParams.set('start', String(start));
      return u.toString();
    }
  }
};

export const SITE_LIST = Object.values(SITES);

export function siteForUrl(url) {
  let host = '';
  try { host = new URL(url).hostname.toLowerCase(); } catch { return null; }
  return SITE_LIST.find((s) => s.host.test(host)) || null;
}

export function defaultSiteSettings() {
  return {
    linkedin: { enabled: true, maxPerRun: 20 },
    // Off by default: each board should be a deliberate choice, and Indeed in
    // particular is covered in bot detection (see indeed.js).
    naukri: { enabled: false, maxPerRun: 15 },
    indeed: { enabled: false, maxPerRun: 10, domain: 'www.indeed.com', autoSubmit: false }
  };
}

// Every host the extension needs permission for, for the manifest and for
// the options page's permission prompt.
export const ALL_SITE_MATCHES = SITE_LIST.flatMap((s) => s.matches);
